"""Random arrays, including one deliberately built to overflow a 32-bit
accumulator but not a 64-bit one."""


def generate(rng, count):
    builders = (_random, _random, _random, _overflow)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, description=""):
    lines = [str(len(values))] + [str(v) for v in values]
    return {"name": name, "stdin": " ".join(lines) + "\n",
            "description": description}


def _random(rng, index):
    n = rng.randint(0, 20)
    values = [rng.randint(-1000, 1000) for _ in range(n)]
    return _case("a random %d-element vector #%d" % (n, index), values)


def _overflow(rng, index):
    values = [rng.randint(1500000000, 2000000000) for _ in range(4)]
    return _case("a sum that overflows a 32-bit int #%d" % index, values,
                 "Four values near 2 billion sum past int.MaxValue.")
